-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 7
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 7 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Individual — Discursivas', 'PENDENTE', v_aula, 'Atividade — Atividade Individual — Discursivas (20 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-SEXTA-FEIRA/ATIVIDADE-INDIVIDUAL-COMUNICACAO-TECNICA-DISCURSIVA.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Identificação dos cinco elementos na situação.', 0.5, 'Emissor: o supervisor do CD. Receptor: o operador da separação. Mensagem: o pedido 1520 é de sabão em pó, não de detergente. Canal: o rádio. Feedback: a resposta "Entendido, vou trocar".', 'Nota cheia: os cinco elementos corretos. Metade: três ou quatro corretos. Zero: dois ou menos.'),
      (v_atividade, 2, 1, 'Conceito de ruído, relação com a situação e atitude preventiva.', 0.5, 'Ruído é tudo o que atrapalha a mensagem a chegar como o emissor quis (barulho, falta de atenção, palavra ambígua). Na situação, a divisão das tarefas não foi entendida igual por todos. Atitudes: registrar os papéis na ata, repetir/confirmar quem faz cada texto, pedir feedback no fim da reunião.', 'Nota cheia: conceito, relação com o caso e uma atitude coerente. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 3, 1, 'Comentário assertivo e explicação.', 0.5, 'Ex.: "Sugiro trocar ''muitos pedidos'' por ''38 dos 150 pedidos'' e ''umas máquinas'' por ''2 dos 6 coletores de dados'', para o gerente entender o tamanho do problema." É assertivo porque é claro, específico, respeitoso e propõe uma solução, sem ofender nem deixar de apontar o erro.', 'Nota cheia: comentário específico, cordial, com sugestão e explicação correta. Metade: comentário adequado sem explicação, ou explicação sem comentário adequado. Zero: comentário agressivo/vago ou em branco.'),
      (v_atividade, 4, 1, 'Conceito de consenso, como buscá-lo e justificativa dos papéis.', 0.5, 'Consenso não é todos pensarem igual: é todos serem ouvidos e concordarem em apoiar a decisão final. Para buscá-lo: ouvir todos, comparar as alternativas por critérios objetivos (prazo, custo, segurança) e combinar uma decisão que todos apoiem. Cada um precisa saber o seu papel, informar o andamento e avisar impedimentos cedo, para evitar o "achei que você já tinha feito" (cap. 01 e 04).', 'Nota cheia: conceito de consenso, como buscá-lo e justificativa dos papéis. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 5, 1, 'Ata em texto corrido, com cabeçalho, decisões e encerramento, verbos no passado.', 0.5, 'Ex.: "Aos nove dias do mês de outubro de dois mil e vinte e seis, às treze horas e trinta minutos, na sala 12, reuniram-se Ana, Bruno, Carla e Davi para dividir as tarefas do Manual de Comunicação do CD. Ficou decidido que Ana será a líder e escreverá a ata; Bruno será o pesquisador e escreverá o relatório; Carla será a redatora e escreverá o memorando; Davi será o formatador e escreverá o e-mail. Encerrou-se a reunião, e a ata foi assinada por Ana, Bruno, Carla e Davi." (cap. 07 — ata: cabeçalho, decisões com responsável, encerramento e assinaturas; verbos no passado; texto corrido; datas por extenso)', 'Nota cheia: texto corrido, cabeçalho (data, hora, local, participantes), decisões, encerramento/assinaturas e verbos no passado. Metade: falta uma dessas partes ou usa tópicos. Zero: não tem forma de ata.'),
      (v_atividade, 6, 1, 'Quatro fatos com horário, setor e números, sem opinião.', 0.5, 'Fatos em ordem de horário (cap. 07 — desenvolvimento: fatos, dados e evidências, sem opinião): 7h30 — Recebimento — 600 caixas guardadas no endereço errado; 8h às 11h — Separação — 38 de 150 pedidos errados; 11h — Armazenagem — 70 caixas de diferença; 13h — Armazenagem — 15 caixas vencidas; 15h — Expedição — 3 horas de atraso; 16h — e-mail falso (phishing).', 'Nota cheia: quatro ou mais fatos com horário, setor e números corretos, sem opinião. Metade: dois ou três fatos corretos, ou com opinião. Zero: um ou nenhum.'),
      (v_atividade, 7, 1, 'Conclusão com quatro causas prováveis, impessoal.', 0.5, 'Causas que aparecem no contexto: o endereço B-03-04 foi trocado por B-04-03 no recebimento; 2 dos 6 coletores de dados pararam de ler o código de barras por problema de driver; as caixas novas de amaciante ficaram na frente das antigas, que venceram; o e-mail falso pediu a senha do sistema. Texto na terceira pessoa, impessoal, com foco no fato e não em quem fez (cap. 07 — conclusão com a causa provável; impessoalidade).', 'Nota cheia: quatro causas do contexto, terceira pessoa, sem culpar pessoas. Metade: duas ou três causas, ou culpa pessoas. Zero: uma causa ou nenhuma.'),
      (v_atividade, 8, 1, 'Cálculo correto e frase técnica.', 0.5, 'Diferença: 320 − 250 = 70 caixas. Ex.: "No inventário das 11h, foram encontradas 250 das 320 caixas previstas no endereço B-03-04, uma diferença de 70 caixas, provavelmente causada pela troca de endereço no recebimento." Frase objetiva, com números e impessoal (cap. 07).', 'Nota cheia: 70 caixas e frase técnica com número e causa. Metade: só o cálculo ou frase sem número correto. Zero: cálculo errado e sem frase.'),
      (v_atividade, 9, 1, 'Frase de fato com números e frase de recomendação, separadas e impessoais.', 0.5, 'Fato: "Constatou-se o vencimento de 15 caixas de amaciante, guardadas no fundo da prateleira, atrás das caixas novas." Recomendação: "Recomenda-se conferir a validade na arrumação e posicionar à frente as caixas que vencem primeiro." Fato e recomendação separados, com números, na terceira pessoa (cap. 07 — separar fato de recomendação; pilares da redação técnica).', 'Nota cheia: fato com número e recomendação, separados e impessoais. Metade: só um dos dois, ou mistura fato com recomendação. Zero: opinião pessoal ou jargão.'),
      (v_atividade, 10, 1, 'Duas recomendações, cada uma ligada a uma causa.', 0.5, 'Ex. (cap. 07 — conclusão com recomendações; "Recomenda-se..."): (1) recomenda-se conferir o endereço no coletor antes de guardar a carga — causa: endereço trocado; (2) instalar ou atualizar o driver dos coletores após cada atualização do sistema — causa: coletores parados; (3) conferir a validade e deixar à frente o que vence primeiro — causa: caixas vencidas; (4) não informar senha por e-mail e avisar o suporte de TI — causa: e-mail falso.', 'Nota cheia: duas recomendações viáveis, cada uma ligada a uma causa do contexto. Metade: uma recomendação ligada, ou duas sem ligação com a causa. Zero: nenhuma recomendação coerente.'),
      (v_atividade, 11, 1, 'Busca com aspas, teste CRAAP com 3 fontes e citação da fonte.', 0.5, 'Busca: usar aspas para a frase exata, ex.: "inventário rotativo" (pode somar site: ou filetype:). Fonte confiável: aplicar o teste CRAAP (atualidade, relevância, autoridade, precisão, propósito), preferir sites oficiais (.gov.br, .edu.br) e confirmar em pelo menos 3 fontes. Uso no texto: escrever com as próprias palavras (citação indireta) ou entre aspas (citação direta), com autor e ano, e listar as referências completas no fim, conforme a ABNT NBR 10520 — copiar sem citar é plágio (cap. 03).', 'Nota cheia: os três elementos corretos. Metade: dois. Zero: um ou nenhum, ou diz para copiar e colar.'),
      (v_atividade, 12, 1, 'Memorando com número, Para, Assunto, solicitação com dados e prazo.', 0.5, 'Ex. (cap. 07 — memorando: número, Para, Assunto, solicitação, prazo): "MEMORANDO Nº 01/2026 — Para: Gerente do CD — Assunto: Pedido de coletores de dados para a separação. Solicitamos a compra de 2 coletores de dados, porque 2 dos 6 equipamentos estão parados desde a atualização do sistema (problema de driver), o que fez 38 dos 150 pedidos saírem errados e atrasou a expedição em 3 horas. Pedimos a compra até 16/10/2026." Aceitar também De, Data, saudação e fecho, se o aluno incluir.', 'Nota cheia: número, Para, Assunto, solicitação com os dados do caso e prazo. Metade: falta uma ou duas partes. Zero: não tem forma de memorando.'),
      (v_atividade, 13, 1, 'Classificação dos três equipamentos com justificativa.', 0.5, 'Pela tabela da apostila (cap. 02): leitor de código de barras — entrada (envia ao computador o código lido). Impressora de etiquetas — saída (entrega o resultado impresso). Coletor de dados — entrada e saída (lê o código de barras e também mostra o pedido na tela).', 'Nota cheia: três classificações corretas e justificadas. Metade: três corretas sem justificativa, ou duas corretas justificadas. Zero: uma ou nenhuma correta.'),
      (v_atividade, 14, 1, 'Conceito de driver, relação com o problema e ordem de verificação.', 0.5, 'Driver é o programa que permite ao sistema controlar o periférico. Depois da atualização, o driver dos coletores pode precisar ser instalado ou atualizado, por isso o equipamento liga, mas não lê. Ordem de verificação: hardware (cabo e porta; testar outra porta) → driver (aparelho com alerta no Gerenciador de Dispositivos?) → configuração do sistema (o dispositivo está habilitado?) (cap. 02).', 'Nota cheia: os três pontos corretos. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 15, 1, 'E-mail completo e adequado ao cliente.', 0.5, 'Ex.: "Para: compras@bompreco-ficticio.com.br — CC: comercial@rotacerta-ficticio.com.br — Assunto: Troca do pedido nº 1520 — sabão em pó. Prezados, pedimos desculpas pelo envio de detergente no lugar de sabão em pó. Houve uma falha na separação do pedido. O produto correto será entregue em 10/10/2026, e o produto enviado por engano será recolhido na mesma entrega. Atenciosamente, [nome] — Atendimento — Rota Certa Logística e Armazenagem."', 'Nota cheia: todos os campos, tom cordial, sem culpar colegas, solução com data, e-mails fictícios. Metade: faltam até dois campos ou a data. Zero: tom inadequado, culpa pessoas ou usa e-mail real.'),
      (v_atividade, 16, 1, 'Função do CC e justificativa sobre a frase.', 0.5, 'CC (com cópia) envia o e-mail também para quem precisa saber do assunto sem ser o destinatário principal; o comercial acompanha a reclamação e a solução do cliente. A frase não deve ser usada porque expõe e culpa um colega, mostra detalhes internos e passa má imagem da empresa; o certo é falar da falha no processo ("houve uma falha na separação").', 'Nota cheia: os dois pontos corretos. Metade: um. Zero: nenhum.'),
      (v_atividade, 17, 1, 'Conceito, dois sinais e conduta correta.', 0.5, 'Phishing é uma mensagem falsa que finge ser de alguém confiável para roubar dados (senhas). Sinais: pede a senha (o suporte nunca pede), urgência/pressa, remetente estranho, erros, links suspeitos. Conduta: não responder, não clicar, não passar a senha, avisar o TI/supervisor e apagar ou reportar o e-mail.', 'Nota cheia: conceito, dois sinais e conduta correta. Metade: dois desses três. Zero: um ou nenhum, ou diz que passaria a senha.'),
      (v_atividade, 18, 1, 'Quatro regras explicadas, em lista numerada, e aviso de atenção.', 0.5, 'Ex. (cap. 05): 1. Crie senha forte, de 12 a 16 caracteres, com letras maiúsculas e minúsculas, números e símbolos, e não a repita em outros sistemas. 2. Ative a autenticação em dois fatores (2FA). 3. Bloqueie a tela ao sair da mesa (Windows + L). 4. Faça backup periódico na nuvem da empresa. ATENÇÃO: nunca informe sua senha por e-mail (cap. 05).', 'Nota cheia: quatro regras corretas e explicadas, lista numerada e aviso de atenção. Metade: três regras ou sem o aviso de atenção. Zero: duas regras ou menos.'),
      (v_atividade, 19, 1, 'Três regras corretas e para que serve cada uma.', 0.5, 'Margens no padrão ABNT: 3 cm em cima e à esquerda, 2 cm embaixo e à direita (espaço entre o texto e a borda). Estilos Título 1 (seções) e Título 2 (subseções): padronizam os títulos e geram o sumário automático (menu Referências ou Inserir), que deve ser atualizado depois de editar. Quebra de página: começa o próximo texto numa página nova sem apertar vários Enter. Número da página no rodapé (cabeçalho e rodapé) (cap. 06).', 'Nota cheia: três regras corretas e para que serve cada uma. Metade: três regras sem a finalidade, ou duas com a finalidade. Zero: uma ou nenhuma correta.'),
      (v_atividade, 20, 1, 'Introdução com contexto, números e objetivo, impessoal.', 0.5, 'Ex.: "A Rota Certa Logística e Armazenagem (empresa fictícia) registrou, na segunda-feira, falhas em seu centro de distribuição: 38 dos 150 pedidos saíram errados, faltaram 70 caixas no inventário, 15 caixas venceram e a expedição atrasou 3 horas, com prejuízo de cerca de R$ 4.200. Este manual tem o objetivo de registrar o ocorrido e padronizar a comunicação do CD." Introdução = contexto e objetivo (cap. 07, ABNT NBR 10719), na terceira pessoa.', 'Nota cheia: empresa, problema com números e objetivo, na terceira pessoa. Metade: falta uma parte ou não usa números. Zero: falta mais de uma parte.');
end $$;
